# attach fwshift-addresses: 0.0.0.0-10.29.255.255 10.31.0.0-203.0.113.127 203.0.113.224-255.255.255.255
G1=$(group 'fwshift-addresses' 'FWShift: for the interfaces of 0.0.0.0-10.29.255.255 10.31.0.0-203.0.113.127 203.0.113.224-255.255.255.255') || exit 1
