G4=$(group 'fwshift-web-nsg' 'FWShift: for the interfaces of 10.30.1.10/31') || exit 1
# attach fwshift-app-subnet-members: 10.30.2.0-10.30.2.29 10.30.2.33-10.30.2.255
G5=$(group 'fwshift-app-subnet-members' 'FWShift: for the interfaces of 10.30.2.0-10.30.2.29 10.30.2.33-10.30.2.255') || exit 1
# attach fwshift-app-nsg: 10.30.2.30-10.30.2.32
G6=$(group 'fwshift-app-nsg' 'FWShift: for the interfaces of 10.30.2.30-10.30.2.32') || exit 1
