G10=$(group 'fwshift-all-fra-services-in-oracle-services-network' 'FWShift: for the interfaces of 203.0.113.128-203.0.113.223') || exit 1
# attach fwshift-addresses-ipv6: ::-2001:db8:2f:ffff:ffff:ffff:ffff:ffff 2001:db8:30:100::-ffff:ffff:ffff:ffff:ffff:ffff:ffff:ffff
G11=$(group 'fwshift-addresses-ipv6' 'FWShift: for the interfaces of ::-2001:db8:2f:ffff:ffff:ffff:ffff:ffff 2001:db8:30:100::-ffff:ffff:ffff:ffff:ffff:ffff:ffff:ffff') || exit 1
# attach fwshift-addresses-ipv6-2: 2001:db8:30::/64 2001:db8:30:2::-2001:db8:30:ff:ffff:ffff:ffff:ffff
G12=$(group 'fwshift-addresses-ipv6-2' 'FWShift: for the interfaces of 2001:db8:30::/64 2001:db8:30:2::-2001:db8:30:ff:ffff:ffff:ffff:ffff') || exit 1
# attach fwshift-Default-Security-List-for-shop-vcn-ipv6: 2001:db8:30:1::/64
